-- PT101-S2-Q3. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT101-S2-Q3$batch05$ AND q.stimulus=$batch05$A group of unusual meteorites was found in Shergotty, India. Their structure indicates that they originated on one of the geologically active planets, Mercury, Venus, or Mars. Because of Mercury’s proximity to the Sun, any material dislodged from that planet’s surface would have been captured by the Sun, rather than falling to Earth as meteorites. Nor could Venus be the source of the meteorites, because its gravity would have prevented dislodged material from escaping into space. The meteorites, therefore, probably fell to Earth after being dislodged from Mars, perhaps as the result of a collision with a large object.$batch05$ AND q.prompt=$batch05$The argument derives its conclusion by$batch05$ AND q.correct_choice=$batch05$B$batch05$) THEN RAISE EXCEPTION 'Question changed: PT101-S2-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT101-S2-Q3$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT101-S2-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT101-S2-Q3$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$The meteorites probably came from Mars.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Their structure points to Mercury, Venus or Mars. Anything knocked off Mercury would have been pulled into the Sun. Venus's gravity would have kept material from escaping.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Three suspects, two alibis. The author starts with a closed list of possible sources, rules out Mercury, rules out Venus, and the one left standing is Mars. That is process of elimination, the same move you would make on a multiple-choice question.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Ruling out the alternatives to leave one explanation.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT101-S2-Q3$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$No theory gets a counterexample. The author is building a case, not knocking one down.$batch05$), ($batch05$B$batch05$, $batch05$Mercury and Venus are the competing explanations, and each is eliminated with its own reason. Mars wins because it is the only one left.$batch05$), ($batch05$C$batch05$, $batch05$Nothing compares the present with the past.$batch05$), ($batch05$D$batch05$, $batch05$The author accepts every premise and questions none of them.$batch05$), ($batch05$E$batch05$, $batch05$The conclusion is about these particular meteorites, not a general principle.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT101-S2-Q3$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
